import json

KEYS = {'Depends', 'Before', 'After', 'Needs', 'Requires', 'Alias', 'Phony'}
SETKEYS = ('Depends', 'Before', 'After', 'Needs', 'Requires')


class _PE(Exception):
    pass


def solve(lines):
    try:
        return _solve(lines)
    except _PE:
        return 'PARSE_ERROR'


def _solve(lines):
    blocks = []
    cur = None
    for raw in lines:
        s = raw.strip()
        if not s or s.startswith('#'):
            continue
        toks = s.split()
        if toks[0] == 'TARGET':
            if len(toks) != 2:
                raise _PE()
            cur = {'kind': 'TARGET', 'name': toks[1], 'id': None, 'dirs': [], 'phony': None}
            blocks.append(cur)
        elif toks[0] == 'OVERRIDE':
            if len(toks) != 3:
                raise _PE()
            cur = {'kind': 'OVERRIDE', 'name': toks[1], 'id': toks[2], 'dirs': [], 'phony': None}
            blocks.append(cur)
        else:
            if '=' not in s and s.startswith('[') and s.endswith(']'):
                continue
            if s.count('=') != 1 or cur is None:
                raise _PE()
            k, v = s.split('=')
            k = k.strip()
            v = v.strip()
            if k not in KEYS:
                raise _PE()
            if k == 'Phony':
                if v not in ('yes', 'no'):
                    raise _PE()
                cur['phony'] = v
            else:
                cur['dirs'].append((k, v.split()))

    universe = set()
    for b in blocks:
        universe.add(b['name'])
        for k, vals in b['dirs']:
            universe.update(vals)

    parent = {u: u for u in universe}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for b in blocks:
        for k, vals in b['dirs']:
            if k == 'Alias':
                for v in vals:
                    ra = find(b['name'])
                    rb = find(v)
                    if ra != rb:
                        parent[max(ra, rb)] = min(ra, rb)

    members = {}
    for u in universe:
        members.setdefault(find(u), []).append(u)
    canon_of_root = {r: min(m) for r, m in members.items()}

    def canon(x):
        return canon_of_root[find(x)]

    ordered = [b for b in blocks if b['kind'] == 'TARGET']
    ordered += sorted([b for b in blocks if b['kind'] == 'OVERRIDE'], key=lambda b: b['id'])

    acc = {}
    for b in ordered:
        t = canon(b['name'])
        a = acc.setdefault(t, {k: set() for k in SETKEYS})
        for k, vals in b['dirs']:
            if k in SETKEYS:
                a[k].update(canon(v) for v in vals)

    nodes = set(canon(u) for u in universe)
    edges = set()
    for U, a in acc.items():
        for x in a['Depends']:
            edges.add((x, U))
        for y in a['Before']:
            edges.add((U, y))
        for z in a['After']:
            edges.add((z, U))
        for w in a['Needs']:
            edges.add((U, w))
        for v in a['Requires']:
            edges.add((U, v))

    adj = {n: set() for n in nodes}
    for x, y in edges:
        adj[x].add(y)

    reach = {}
    for n in nodes:
        seen = {n}
        stack = [n]
        while stack:
            x = stack.pop()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        reach[n] = seen

    comp_list = []
    assigned = set()
    for n in sorted(nodes):
        if n in assigned:
            continue
        comp = sorted(m for m in reach[n] if n in reach[m])
        assigned.update(comp)
        comp_list.append(comp)

    comp_of = {}
    for i, c in enumerate(comp_list):
        for m in c:
            comp_of[m] = i

    cycles = []
    for c in comp_list:
        if len(c) >= 2 or (c[0], c[0]) in edges:
            cycles.append(c)
    cycles.sort()

    n_c = len(comp_list)
    cadj = [set() for _ in range(n_c)]
    indeg = [0] * n_c
    for x, y in edges:
        i = comp_of[x]
        j = comp_of[y]
        if i != j and j not in cadj[i]:
            cadj[i].add(j)
            indeg[j] += 1

    avail = [i for i in range(n_c) if indeg[i] == 0]
    order = []
    while avail:
        avail.sort(key=lambda i: comp_list[i][0])
        i = avail.pop(0)
        order.extend(comp_list[i])
        for j in cadj[i]:
            indeg[j] -= 1
            if indeg[j] == 0:
                avail.append(j)

    return json.dumps({'order': order, 'cycles': cycles}, separators=(',', ':'))
